<script setup>
import {computed,onBeforeUnmount,onMounted,ref} from 'vue';import {router,usePage} from '@inertiajs/vue3';import PortalLayout from '../../../Layouts/PortalLayout.vue';
const p=defineProps({attempt:Object,exam:Object,questions:Array});const page=usePage();const hi=computed(()=>page.props.locale==='hi');
const index=ref(0),seconds=ref(0),saving=ref(false);let timer;
const current=computed(()=>p.questions[index.value]);const answers=ref(Object.fromEntries(p.questions.map(q=>[q.id,q.answer||[]])));const review=ref(Object.fromEntries(p.questions.map(q=>[q.id,q.marked_for_review||false])));
const answered=computed(()=>Object.values(answers.value).filter(a=>a?.some(v=>v!==''&&v!==null)).length);
const clock=computed(()=>String(Math.floor(seconds.value/60)).padStart(2,'0')+':'+String(seconds.value%60).padStart(2,'0'));
function save(q){if(!q||saving.value)return;saving.value=true;router.put('/student/attempts/'+p.attempt.id+'/answers/'+q.id,{answer:answers.value[q.id],marked_for_review:review.value[q.id]},{preserveScroll:true,onFinish:()=>saving.value=false});}
function select(v){const q=current.value;if(q.type==='multiple_choice'){const a=answers.value[q.id]||[];answers.value[q.id]=a.includes(v)?a.filter(x=>x!==v):[...a,v];}else answers.value[q.id]=[v];save(q);}
function short(event){answers.value[current.value.id]=[event.target.value];save(current.value);}
function mark(){review.value[current.value.id]=!review.value[current.value.id];save(current.value);}
function submit(auto=false){if(!auto&&!confirm(hi.value?'क्या आप परीक्षा जमा करना चाहते हैं?':'Submit your exam now?'))return;router.post('/student/attempts/'+p.attempt.id+'/submit');}
function tick(){seconds.value=Math.max(0,Math.floor((new Date(p.attempt.expires_at).getTime()-Date.now())/1000));if(seconds.value===0)submit(true);}
onMounted(()=>{tick();timer=setInterval(tick,1000)});onBeforeUnmount(()=>clearInterval(timer));
</script>
<template><PortalLayout portal="student" :title="exam.title" :subtitle="hi?'आपके उत्तर स्वतः सेव होते हैं।':'Your answers are saved automatically.'">
<div class="mb-4 flex items-center justify-between rounded-xl border bg-white p-4"><div><p class="text-xs font-bold uppercase text-slate-500">{{hi?'समय शेष':'Time remaining'}}</p><p class="text-2xl font-black tabular-nums" :class="seconds<60?'text-rose-600':'text-slate-900'">{{clock}}</p></div><span class="text-sm text-slate-600">{{hi?'उत्तर दिए':'Answered'}}: {{answered}}/{{questions.length}}</span><button @click="submit()" class="rounded-lg bg-rose-600 px-4 py-2 font-bold text-white">{{hi?'जमा करें':'Submit exam'}}</button></div>
<div class="grid gap-5 lg:grid-cols-[1fr_260px]"><section class="rounded-2xl border bg-white p-5"><div class="flex justify-between text-sm font-bold text-indigo-700">{{hi?'प्रश्न':'Question'}} {{index+1}} / {{questions.length}}<span class="text-slate-500">{{current.marks}} {{hi?'अंक':'marks'}}</span></div>
<h2 class="mt-5 whitespace-pre-wrap text-lg font-bold leading-8">{{current.prompt}}</h2>
<input v-if="current.type==='short_answer'" :value="answers[current.id]?.[0]||''" @change="short" class="mt-5 w-full rounded-lg border p-3" :placeholder="hi?'अपना उत्तर लिखें':'Type your answer'">
<div v-else class="mt-5 space-y-3"><label v-for="(v,k) in current.options" :key="k" class="flex cursor-pointer gap-3 rounded-xl border p-3 hover:bg-slate-50"><input class="mt-1" :type="current.type==='multiple_choice'?'checkbox':'radio'" :checked="answers[current.id]?.includes(k)" @change="select(k)"><span class="text-sm"><b class="mr-2">{{k}}.</b>{{v}}</span></label></div>
<div class="mt-7 flex flex-wrap items-center justify-between gap-2 border-t pt-4"><button @click="mark" class="rounded-lg border px-3 py-2 text-sm">{{review[current.id]?(hi?'समीक्षा हटाएँ':'Unmark review'):(hi?'समीक्षा के लिए चिह्नित करें':'Mark for review')}}</button><div class="flex gap-2"><button @click="index=Math.max(0,index-1)" :disabled="index===0" class="rounded-lg border px-4 py-2 disabled:opacity-40">{{hi?'पिछला':'Previous'}}</button><button @click="index=Math.min(questions.length-1,index+1)" :disabled="index===questions.length-1" class="rounded-lg bg-indigo-600 px-4 py-2 font-bold text-white disabled:opacity-40">{{hi?'अगला':'Next'}}</button></div></div><p v-if="saving" class="mt-2 text-xs text-slate-400">{{hi?'सेव हो रहा है':'Saving...'}}</p></section>
<aside class="h-fit rounded-2xl border bg-white p-4"><h3 class="font-bold">{{hi?'प्रश्न सूची':'Question palette'}}</h3><div class="mt-3 grid grid-cols-5 gap-2"><button v-for="(q,i) in questions" :key="q.id" @click="index=i" :class="['rounded-lg border p-2 text-sm font-bold',index===i?'bg-indigo-600 text-white':answers[q.id]?.length?'bg-emerald-50 text-emerald-800':'bg-slate-50',review[q.id]?'ring-2 ring-amber-400':'']">{{i+1}}</button></div><p class="mt-3 text-xs text-slate-500">{{hi?'हरा: उत्तर दिया · पीला: समीक्षा':'Green: answered · Amber: review'}}</p></aside></div>
</PortalLayout></template>